133	  // Columnas de tablas cuyo encabezado indica un valor temporal: se marcan por el TEXTO del encabezado,
134	  // no por posición (la posición cambia entre informes y vistas).
135	  await page.evaluate((patron) => {
136	    const re = new RegExp(patron, 'i');
137	    // La tabla de resumen va en vertical: sus filas dinámicas se marcan abajo, una por una, y sus etiquetas quedan visibles.
138	    document.querySelectorAll('table:not(.quizreviewsummary)').forEach((t) => {
139	      const ths = Array.from(t.querySelectorAll('thead th, tr:first-child th'));
140	      ths.forEach((th, i) => {
141	        if (!re.test((th.textContent || '').trim())) return;
142	        t.querySelectorAll('tbody tr').forEach((tr) => tr.children[i]?.setAttribute('data-qa-mascara', 'tiempo'));
143	      });
