145	  }, '^(comenzado|completado|duración|enviado|tiempo|hora|estado)');
146	  // La máscara se pinta en la página y no con `mask`: Playwright no admite maskColor global y sale magenta en cada captura.
147	  const dinamicos = [filaResumen(page, 'Comenzado'), filaResumen(page, 'Completado'), filaResumen(page, 'Duración'),
148	    page.locator('#quiz-timer-wrapper'), page.locator('.popover-region .count-container')];
