1	// Soporte exclusivo de las pruebas de spec-0. Complementa factory/regresion/helpers.ts (que este spec no puede editar).
2	// Selectores tomados del código de Moodle 5.3 en entorno/.moodle-src/. Las aserciones que deciden si un criterio se
3	// cumple están en los .spec.ts; acá solo hay esperas y comprobaciones de que cada paso auxiliar terminó bien.
4	import { expect, type Locator, type Page } from '@playwright/test';
5	import { bloquePregunta } from '../../../factory/regresion/helpers';
6	
7	export type TipoPregunta = 'multichoice' | 'truefalse' | 'essay';
8	export type Categoria = { id: string; contexto: string };
9	
10	type ConfigMoodle = { courseId: number; contextid: number; sesskey: string };
11	
12	const configMoodle = (page: Page): Promise<ConfigMoodle> =>
13	  page.evaluate(() => (window as unknown as { M: { cfg: ConfigMoodle } }).M.cfg);
14	
15	/** Nombre único que no contiene "Examen de regresión", para que abrirQuiz nunca tome este examen por QUIZ-REG. */
16	export const nombreUnico = (prefijo: string, proyecto: string) => `${prefijo} ${proyecto} ${Date.now()}`;
17	
18	/**
19	 * TinyMCE crea su iframe oculto y lo muestra al terminar de cargar sus módulos, lo que puede superar los 5 s por defecto
20	 * de expect con el servidor bajo carga. Es una espera de carga: la aserción sobre el editor no cambia.
21	 */
22	export const ESPERA_EDITOR = 30_000;
23	
24	/**
25	 * Espera a que terminen de inicializarse los módulos AMD de la página (misma señal que usa Behat y enviarIntento() de
26	 * helpers.ts). Sustituye a 'networkidle', que en Moodle nunca se cumple por sus peticiones periódicas.
27	 */
28	export async function esperarModulos(page: Page) {
29	  await page.waitForLoadState('load');
30	  await page.waitForFunction(() => (window as unknown as { M?: { util?: { pending_js?: unknown[] } } }).M?.util?.pending_js?.length === 0);
31	}
32	
33	export async function idCursoQA101(page: Page): Promise<number> {
34	  await page.goto('/course/view.php?name=QA101');
35	  return (await configMoodle(page)).courseId;
36	}
37	
38	// ---------------------------------------------------------------------------------------------------------
39	// Examen
40	
41	export async function abrirFormularioExamen(page: Page, curso: number) {
42	  await page.goto(`/course/modedit.php?add=quiz&course=${curso}&section=0`);
43	  await expect(page.locator('#id_introeditor_ifr')).toBeVisible({ timeout: ESPERA_EDITOR });
44	}
45	
46	/**
47	 * Deja cerrado el índice del curso (solo escritorio) para capturar siempre el mismo estado, el que ya tiene móvil
48	 * (drawers.js:328 lo cierra al cargar). Abierto o cerrado es una preferencia guardada por usuario (drawer-open-index,
49	 * boost/layout/drawers.php:34) que sobrevive entre corridas: no es parte de la pantalla que se protege. Se elige cerrado
50	 * porque con el cajón abierto M.util.pending_js no llegaba a vaciarse y prepararCaptura() (esperarJS) agotaba su tiempo.
51	 */
52	export async function cerrarIndiceCurso(page: Page) {
53	  const drawer = page.locator('#theme_boost-drawers-courseindex');
54	  if (await drawer.evaluate((el) => el.classList.contains('show'))) {
55	    await drawer.locator('[data-toggler="drawers"][data-action="closedrawer"]').click();
56	  }
57	  // El cajón abierto lleva la clase "show" (drawers.mustache:66); no depende del idioma del botón.
58	  await expect(drawer).not.toHaveClass(/\bshow\b/);
59	  await esperarModulos(page);
60	}
61	
62	/** Guarda con "Guardar cambios y mostrar" (#id_submitbutton) y devuelve el cmid del examen creado o editado. */
63	export async function guardarExamen(page: Page): Promise<number> {
64	  await page.locator('#id_submitbutton').click();
65	  await expect(page).toHaveURL(/mod\/quiz\/view\.php\?id=\d+/);
66	  return Number(new URL(page.url()).searchParams.get('id'));
67	}
68	
69	export async function crearExamen(page: Page, curso: number, nombre: string): Promise<number> {
70	  await abrirFormularioExamen(page, curso);
71	  await page.locator('#id_name').fill(nombre);
72	  return guardarExamen(page);
73	}
74	
75	export async function eliminarExamen(page: Page, cmid: number) {
76	  const { sesskey } = await configMoodle(page);
77	  await page.goto(`/course/mod.php?delete=${cmid}&sesskey=${sesskey}`);
78	  await page.getByRole('button', { name: 'Sí', exact: true }).click();
79	  await expect(page).toHaveURL(/course\/(view|section)\.php/);
80	}
81	
82	// ---------------------------------------------------------------------------------------------------------
83	// Banco de preguntas
84	
85	/** cmid del banco compartido de QA101, leído de la lista de bancos del curso. */
86	export async function cmidBanco(page: Page, curso: number): Promise<number> {
87	  await page.goto(`/question/banks.php?courseid=${curso}`);
88	  const banco = page.locator('.shared-banks .questioncount[data-cmid]').first();
89	  await expect(banco).toBeAttached();
90	  return Number(await banco.getAttribute('data-cmid'));
