1	#!/usr/bin/env node
2	// Fábrica: un comando por spec.
3	//   node factory/cli.mjs run specs/spec-1-reconocimiento.md      pipeline completo -> rama + PR (sin merge)
4	//   node factory/cli.mjs suite                                   suite completa funcional + visual + honestidad
5	//   node factory/cli.mjs honestidad                              solo el control de verificación honesta
6	//   node factory/cli.mjs aprobar-linea-base <png|--pendientes> --razon "..."   (HUMANO)
7	//   node factory/cli.mjs aprobar-pruebas --razon "..."                          (HUMANO)
8	import fs from 'node:fs';
9	import path from 'node:path';
10	import { RAIZ, Corrida, sh, shOk, escribir, leer, existe, archivos } from './lib/util.mjs';
11	import { llamarIA, extraerJSON } from './lib/ia.mjs';
12	import * as moodle from './lib/moodle.mjs';
13	import { correrPruebas, resumen, contextoFallos, copiasDeHelpers } from './lib/pruebas.mjs';
14	import { auditar } from './lib/auditor.mjs';
15	import { generarTrazabilidad } from './lib/trazabilidad.mjs';
16	import { lineasBaseNuevas, registrarPendientes, proponerLineasBase, aprobarLineaBase } from './lib/lineas-base.mjs';
17	
18	const MAX_REINTENTOS = Number(process.env.FACTORY_REINTENTOS || 3);
19	const [, , comando, ...resto] = process.argv;
20	const opt = (n) => { const i = resto.indexOf(n); return i >= 0 ? resto[i + 1] : null; };
21	const ETAPAS_RUN = ['precondicion', 'analisis', 'sondas', 'implementacion', 'pruebas', 'mutacion', 'regresion', 'alcance', 'honestidad', 'pr'];
22	// Reglas del auditor que se ven sin ejecutar nada: mejor corregirlas antes de gastar una corrida de pruebas.
23	const REGLAS_ESTATICAS = new Set(['SIN-ASSERTS', 'ASSERT-TRIVIAL', 'ASSERT-SIN-AWAIT', 'ERROR-TRAGADO', 'RED-SIMULADA', 'TEST-ONLY', 'OMISION-NUEVA', 'OMITIDA']);
24	const ETAPAS_SUITE = ['precondicion', 'pruebas', 'honestidad'];
25	let corridaActiva = null;
26	
27	const comandos = { run, suite, honestidad, 'aprobar-linea-base': aprobarLB, 'aprobar-pruebas': aprobarPruebas };
28	if (!comandos[comando]) { console.error(`Uso: node factory/cli.mjs <${Object.keys(comandos).join('|')}> ...`); process.exit(2); }
29	try { process.exitCode = await comandos[comando](); } catch (e) {
30	  // Una excepción no debe dejar estado.json diciendo que la etapa sigue en curso.
31	  const enCurso = corridaActiva?.etapaEnCurso();
32	  if (e.limiteIA) {
33	    if (enCurso) corridaActiva.etapa(enCurso, 'BLOQUEADO', `Límite de uso de la IA: ${e.message}`);
34	    console.error(`\n⛔ ${e.message}\nLa corrida quedó en su rama. Cuando la IA vuelva a estar disponible:\n  node factory/cli.mjs run <spec> --reanudar $(git branch --show-current)`);
35	    process.exitCode = 3;
36	  } else {
37	    if (enCurso) corridaActiva.etapa(enCurso, 'FALLIDO', String(e.message || e).slice(0, 500));
38	    console.error(e.stack || e); process.exitCode = 1;
39	  }
40	}
41	
42	// ---------------------------------------------------------------------------------------------------------
43	async function run() {
44	  const specPath = resto.find((a) => !a.startsWith('--'));
45	  if (!specPath || !existe(specPath)) throw new Error(`Spec no encontrado: ${specPath}`);
46	  const specTxt = leer(specPath);
47	  const specId = (specTxt.match(/^id:\s*(\S+)/m) || [])[1] || path.basename(specPath, '.md');
48	  const specDir = `salidas/${specId}`;
49	  const c = corridaActiva = new Corrida(specId);
50	  // --reanudar <rama>: retoma una corrida interrumpida (p. ej. por límite de uso de la IA) reutilizando el plan
51	  // y el código ya generados en esa rama; vuelve a ejecutar TODAS las verificaciones desde la etapa 4.
52	  const reanudar = opt('--reanudar');
53	  const rama = reanudar || `factory/${specId}-${c.id.slice(0, 15)}`;
54	  c.iniciarEstado(ETAPAS_RUN, { spec: specPath, rama, reanudada: Boolean(reanudar) });
55	  c.log('inicio', `Spec ${specPath} (${specId}). Corrida ${c.dir}. Rama ${rama}${reanudar ? ' (REANUDADA)' : ''}.`);
56	
57	  // 0. Precondiciones
58	  if (!moodle.moodleArriba()) return falla(c, 'precondicion', 'Moodle no responde en http://localhost:8090. Ejecutar: bash entorno/setup.sh');
59	  // La carpeta de esta misma corrida ya existe (es donde se escribe el log): no cuenta como cambio.
60	  const sucio = sh('git status --porcelain').out.split('\n').filter((l) => l && !l.slice(3).startsWith('corridas/')).join('\n');
61	  if (sucio) return falla(c, 'precondicion', 'El árbol de trabajo tiene cambios sin commit. La fábrica parte de un estado limpio.', sucio);
62	  if (reanudar) {
63	    shOk(`git checkout -q ${reanudar}`);
64	    // La fábrica de main (con sus correcciones) es la que verifica; la rama solo aporta plan, código y pruebas.
65	    shOk('git checkout -q main -- factory entorno playwright.config.ts package.json .gitignore');
66	    if (!existe(`${specDir}/plan.json`)) return falla(c, 'reanudar', `La rama ${reanudar} no tiene ${specDir}/plan.json.`);
67	  } else {
68	    shOk(`git checkout -q -b ${rama}`);
69	    fs.rmSync(path.join(RAIZ, specDir), { recursive: true, force: true });
70	    escribir(`${specDir}/spec.md`, specTxt);
71	  }
72	  c.etapa('precondicion', 'VALIDADO', 'Moodle responde y el árbol de trabajo está limpio.');
73	
74	  // 1. Análisis: plan, capa, bordes, criterios -> pruebas
75	  let plan = reanudar ? validarPlan(JSON.parse(leer(`${specDir}/plan.json`)), specId) : null;
76	  if (reanudar) c.log('reanudar', `Se reutiliza ${specDir}/plan.json y el código/pruebas de la rama. Análisis e implementación no se repiten.`);
77	  let feedback = '';
78	  for (let i = 1; i <= 3 && !plan; i++) {
79	    const lineas_base = fs.readdirSync(path.join(RAIZ, 'visual/lineas-base')).filter((f) => f.endsWith('.png')).join(', ') || '(ninguna todavía)';
80	    const r = llamarIA(c, { rol: 'analista', plantilla: 'analista', vars: { spec: specTxt, spec_id: specId, conocimiento: leer('factory/conocimiento/moodle-5.3.md'), helpers: leer('factory/regresion/helpers.ts'), feedback, lineas_base } });
81	    try {
82	      plan = validarPlan(extraerJSON(r.texto), specId);
83	      c.log('analisis', `Plan válido en intento ${i}: capa ${plan.componente || '(solo pruebas)'} — ${plan.criterios.length} criterios, ${plan.bordes.length} bordes.`);
84	    } catch (e) {
85	      feedback = `Tu respuesta anterior no es un plan válido: ${e.message}. Devolvé SOLO el bloque \`\`\`json con el esquema pedido.`;
86	      c.log('analisis', `Plan inválido (intento ${i}), se reintenta.`, e.message);
87	    }
88	  }
89	  if (!plan) return falla(c, 'analisis', 'La IA no produjo un plan válido en 3 intentos.');
90	  escribir(`${specDir}/plan.json`, JSON.stringify(plan, null, 2));
91	  // Una ambigüedad que solo producto puede resolver detiene la corrida antes de gastar en construir.
92	  const bloqueantes = plan.bordes.filter((b) => b.bloqueante === true);
93	  if (bloqueantes.length) return bloquear(c, rama, specDir, specPath, bloqueantes);
94	  c.etapa('analisis', 'VALIDADO', `${reanudar ? 'Plan reutilizado de la rama' : 'Plan válido'}: ${plan.criterios.length} criterios, ${plan.bordes.length} bordes.`);
95	
96	  // 2. Sondas: verificar contra la realidad antes de construir (contratos externos, comportamiento actual)
97	  const sondas = ejecutarSondas(c, plan.sondas || []);
98	  escribir(`${specDir}/sondas.json`, JSON.stringify(sondas, null, 2));
99	  c.etapa('sondas', 'EJECUTADO', `${sondas.length} sonda(s).`);
100	
101	  // 3. Implementación (código + pruebas)
102	  const varsImpl = { spec: specTxt, spec_id: specId, plan, sondas, conocimiento: leer('factory/conocimiento/moodle-5.3.md'), helpers: leer('factory/regresion/helpers.ts'), spec_dir: specDir };
103	  if (!reanudar) llamarIA(c, { rol: 'implementador', plantilla: 'implementador', vars: varsImpl, escritura: specDir });
104	  const noAplicados = aplicarPruebasAfectadas(c, plan);
105	  if (noAplicados.length) return falla(c, 'implementacion', 'Una prueba declarada en pruebas_afectadas no se pudo actualizar.', noAplicados.join('\n'));
106	  c.etapa('implementacion', 'EJECUTADO', reanudar ? 'Código y pruebas reutilizados de la rama.' : 'Código y pruebas generados.');
107	  // Adelanta las llamadas caras sin usar Moodle: las pruebas se hacen después con --reanudar.
108	  if (process.env.FACTORY_SOLO_GENERAR) {
109	    shOk(`git add -A ${specDir} ${c.dir} ia/transcripciones`);
110	    shOk(`git commit -q -m "feat(${specId}): plan e implementación generados" -m "Corrida ${c.dir}. Pendiente de pruebas: --reanudar."`);
111	    shOk('git checkout -q main');
112	    return 0;
113	  }
114	
115	  // 4. Bucle validar -> desplegar -> probar -> corregir
116	  let verde = false;
117	  let res = null;
118	  for (let intento = 1; intento <= MAX_REINTENTOS + 1; intento++) {
119	    const problemas = validacionesEstaticas(c, specDir, plan);
120	    let detalle = problemas.join('\n');
121	    if (!problemas.length) {
122	      const d = moodle.desplegar(specDir);
123	      c.log('despliegue', `Plugins: ${d.plugins.map((p) => p.componente).join(', ') || '(ninguno)'} — upgrade ${d.ok ? 'OK' : 'FALLÓ'}`, d.ok ? null : d.salida);
124	      if (!d.ok) detalle = `La actualización de Moodle falló:\n${d.salida}`;
125	      else {
126	        moodle.reset();
127	        const pruebasSpec = archivos(`${specDir}/pruebas`, (f) => f.endsWith('.spec.ts'));
128	        res = correrPruebas(pruebasSpec, c.ruta('spec'), { crearLineasBaseFaltantes: true });
129	        const s = resumen(res.resultados);
130	        c.log('pruebas', `Intento ${intento}: ${s.passed} OK, ${s.failed} fallidas, ${s.skipped} omitidas.`, s.failed ? contextoFallos(c.ruta('spec'), res.resultados) : null);
131	        if (s.failed === 0 && s.passed > 0) { verde = true; break; }
132	        detalle = s.passed + s.failed === 0 ? `No se ejecutó ninguna prueba.\n${res.salida.slice(-3000)}` : contextoFallos(c.ruta('spec'), res.resultados);
133	      }
134	    }
135	    if (intento > MAX_REINTENTOS) break;
136	    c.log('reintento', `Intento ${intento} no quedó verde. Se le pide a la IA que corrija (${intento}/${MAX_REINTENTOS}).`);
137	    llamarIA(c, { rol: 'corrector', plantilla: 'corrector', vars: { ...varsImpl, problemas: detalle, intento: String(intento) }, escritura: specDir });
138	  }
139	  if (!verde) return falla(c, 'pruebas', `Las pruebas del spec no quedaron en verde tras ${MAX_REINTENTOS} reintentos. Se detiene sin PR; la rama ${rama} queda para diagnóstico.`);
140	  c.etapa('pruebas', 'VALIDADO', 'Pruebas del spec en verde.');
141	
142	  // 5. Mutación "sin la funcionalidad": las pruebas @requiere-feature deben fallar sin el plugin
143	  let sinFeature = null;
144	  const probarSinFuncionalidad = () => {
145	    if (!moodle.pluginsDe(specDir).length) { c.etapa('mutacion', 'EJECUTADO', 'No aplica: el spec no trae plugin.'); return; }
146	    const r = moodle.retirar(specDir);
147	    c.log('mutacion', `Plugin retirado para probar que las pruebas detectan su ausencia (${r.ok ? 'OK' : 'con avisos'}).`);
148	    moodle.reset();
149	    const pruebasSpec = archivos(`${specDir}/pruebas`, (f) => f.endsWith('.spec.ts'));
150	    sinFeature = correrPruebas(pruebasSpec, c.ruta('sin-feature'), { grep: '@requiere-feature' }).resultados;
151	    const s = resumen(sinFeature);
152	    c.log('mutacion', `Sin la funcionalidad: ${s.failed} fallan (esperado), ${s.passed} pasan (cada una es un hallazgo).`);
153	    moodle.desplegar(specDir);
154	    c.etapa('mutacion', s.passed ? 'EJECUTADO' : 'VALIDADO', `Sin la funcionalidad: ${s.failed} fallan, ${s.passed} pasan.`);
155	  };
156	  probarSinFuncionalidad();
157	
158	  // 6. Regresión completa (nada de lo existente se rompió) + líneas base nuevas
159	  moodle.reset();
160	  let total = correrPruebas([], c.dir, { crearLineasBaseFaltantes: false });
161	  // Pantallas que el spec declara cambiar A PROPÓSITO: la imagen obtenida se PROPONE como nueva línea base,
162	  // pendiente de aprobación humana en el PR. Diferencias en pantallas NO declaradas siguen siendo fallos.
163	  const propuestas = proponerCambiosVisuales(c, plan, total.resultados);
164	  if (propuestas.length) {
165	    c.log('visual', `Cambios visuales declarados por el plan (${plan.pantallas_afectadas.join(', ')}): se proponen ${propuestas.length} líneas base, pendientes de aprobación humana.`, propuestas.join('\n'));
166	    copiarDiferencias(c);
167	    moodle.reset();
168	    total = correrPruebas([], c.dir, { crearLineasBaseFaltantes: false });
169	  }
170	  // Una prueba del propio spec que pasó sola y falla en la suite es inestable: va al corrector igual que en la etapa 4.
171	  // Los fallos de pruebas de otros specs no se corrigen aquí: son regresiones y detienen la corrida.
172	  for (let i = 1; i <= MAX_REINTENTOS; i++) {
173	    const propias = total.resultados.filter((r) => ['failed', 'timedOut', 'interrupted'].includes(r.estado) && (r.archivo || '').includes(specDir));
174	    if (!propias.length) break;
175	    c.log('reintento', `${propias.length} prueba(s) del spec fallaron en la suite completa. Se le pide a la IA que corrija (${i}/${MAX_REINTENTOS}).`);
176	    const problemas = `Estas pruebas pasaron ejecutadas solas y fallaron en la suite completa: son inestables. Buscá una carrera entre una acción y el JS de Moodle (usá esperarJS de los helpers).\nEl estado ARIA puede ser posterior a la limpieza de la prueba; guiate por la línea del error.\n\n${contextoFallos(c.dir, total.resultados)}`;
177	    llamarIA(c, { rol: 'corrector', plantilla: 'corrector', vars: { ...varsImpl, problemas, intento: `regresion-${i}` }, escritura: specDir });
178	    const estaticos = validacionesEstaticas(c, specDir, plan);
179	    if (estaticos.length) return falla(c, 'regresion', 'La corrección de la regresión no pasa las validaciones estáticas.', estaticos.join('\n'));
180	    moodle.desplegar(specDir);
181	    probarSinFuncionalidad(); // las pruebas cambiaron: el resultado anterior ya no vale
182	    moodle.reset();
183	    total = correrPruebas([], c.dir, { crearLineasBaseFaltantes: false });
184	  }
185	  const st = resumen(total.resultados);
186	  c.log('regresion', `Suite completa: ${st.passed} OK, ${st.failed} fallidas, ${st.skipped} omitidas.`, st.failed ? contextoFallos(c.dir, total.resultados) : null);
187	  c.etapa('regresion', st.failed ? 'EJECUTADO' : 'VALIDADO', `${st.passed} OK, ${st.failed} fallidas, ${st.skipped} omitidas.`);
188	  const nuevas = lineasBaseNuevas();
189	  if (nuevas.length) { registrarPendientes(nuevas, specId); c.log('visual', `Líneas base NUEVAS (pantallas que introduce el spec), pendientes de aprobación humana en el PR: ${nuevas.join(', ')}`); }
190	
191	  // 7. Alcance: la IA solo pudo cambiar salidas/<spec>/ y líneas base nuevas; el core de Moodle intacto
192	  const fuera = sh('git status --porcelain').out.split('\n').filter(Boolean).map((l) => l.slice(3))
193	    .filter((f) => !(plan.pruebas_afectadas || []).some((d) => d.archivo === f))
194	    .filter((f) => !f.startsWith(specDir) && !f.startsWith('corridas/') && !f.startsWith('ia/transcripciones/') && !f.startsWith('visual/') && !f.startsWith('test-results'))
195	    // al reanudar, la fábrica se toma de main (no de la rama): esas diferencias no son obra de la IA
196	    .filter((f) => !(reanudar && sh(`git diff --quiet main -- '${f}'`).code === 0));
197	  const core = moodle.verificarCoreIntacto(rutasPluginsDesplegados());
198	  if (fuera.length || core.length) return falla(c, 'alcance', 'Cambios fuera del alcance permitido.', [...fuera.map((f) => `repo: ${f}`), ...core.map((x) => `core moodle: ${x}`)].join('\n'));
199	  c.log('alcance', 'Solo cambió salidas/ del spec; core de Moodle intacto (git status del árbol de Moodle).');
200	  c.etapa('alcance', 'VALIDADO', 'Solo cambió salidas/ del spec; core de Moodle intacto.');
201	
202	  // 8. Control de verificación honesta (independiente). Bloquea.
203	  const { hallazgos: H, texto: txtH } = auditar({ resultados: total.resultados, sinFeature, plan });
204	  escribir(c.ruta('honestidad.log'), txtH);
205	  c.log('honestidad', H.length ? `BLOQUEADO con ${H.length} hallazgo(s).` : 'OK.', txtH);
206	  if (H.length) return falla(c, 'honestidad', 'El control de verificación honesta bloqueó la corrida. No se abre PR.');
207	  c.etapa('honestidad', 'VALIDADO', 'Sin hallazgos.');
208	  if (st.failed) return falla(c, 'regresion', 'La regresión completa tiene fallos. No se abre PR.');
209	
210	  // 9. Evidencia, trazabilidad, diff, commit, PR (sin merge)
211	  generarTrazabilidad({ plan, specDir, resultados: total.resultados, corrida: c });
212	  shOk(`git add -A ${specDir} visual/lineas-base`);
213	  const diff = sh(`git diff --cached -- ${specDir}/codigo visual/lineas-base`).out;
214	  escribir(`${specDir}/cambios.diff`, diff || '(sin cambios de código: spec de solo pruebas)\n');
215	  shOk(`git add -A ${specDir} ${c.dir} ia/transcripciones visual/lineas-base`);
216	  shOk(`git commit -q -m "feat(${specId}): ${plan.titulo}" -m "Generado por la fábrica. Corrida ${c.dir}."`);
217	  const pr = abrirPR(c, rama, plan, specDir, st, txtH, nuevas);
218	  c.etapa('pr', 'EJECUTADO', `PR propuesto: ${pr}. Pendiente de aprobación humana.`);
219	  c.log('fin', `PR propuesto: ${pr}. El pipeline se detiene en aprobación humana: no mergea ni despliega.`);
220	  // El plugin vive en su rama: dejarlo instalado haría fallar el control de core del spec siguiente.
221	  moodle.retirar(specDir);
222	  sh(`git add -A ${c.dir} && git commit -q -m "chore(${specId}): log final de la corrida" && git push -q origin ${rama}`);
223	  shOk('git checkout -q main');
224	  return 0;
225	}
226	
227	function proponerCambiosVisuales(c, plan, resultados) {
228	  const afectadas = plan.pantallas_afectadas || [];
229	  if (!afectadas.length) return [];
230	  const art = path.join(RAIZ, c.dir, 'artefactos');
231	  if (!fs.existsSync(art)) return [];
232	  const hechas = [];
233	  for (const f of fs.readdirSync(art, { recursive: true }).filter((x) => x.endsWith('-actual.png'))) {
234	    // Playwright nombra el artefacto <nombre-captura>-actual.png; la línea base es <nombre>--<proyecto>.png
235	    const nombre = path.basename(f).replace(/-actual\.png$/, '');
236	    const proyecto = /-movil$/.test(path.dirname(f)) ? 'movil' : 'escritorio';
237	    if (!afectadas.some((p) => nombre.startsWith(p))) continue;
238	    const destino = `visual/lineas-base/${nombre}--${proyecto}.png`;
239	    if (!fs.existsSync(path.join(RAIZ, destino))) continue;
240	    fs.copyFileSync(path.join(art, f), path.join(RAIZ, destino));
241	    hechas.push(destino);
242	  }
243	  if (hechas.length) proponerLineasBase(hechas.map((h) => path.basename(h)), plan.spec_id);
244	  void resultados;
245	  return hechas;
246	}
247	
248	function falla(c, etapa, msg, detalle) {
249	  c.log(etapa, `DETENIDO: ${msg}`, detalle);
250	  c.etapa(etapa === 'reanudar' ? 'precondicion' : etapa, 'FALLIDO', msg);
251	  return 1;
252	}
253	
254	/** Detiene la corrida en BLOQUEADO: deja pregunta.md y el plan en la rama, y vuelve a main sin construir nada. */
255	function bloquear(c, rama, specDir, specPath, bordes) {
256	  const preguntas = bordes.map((b, i) => `## ${i + 1}. ${b.descripcion}\n\n**Pregunta:** ${b.preguntaria}\n\n**Por qué bloquea:** ${b.criterio || '(sin criterio declarado)'}\n`).join('\n');
257	  const md = `# Corrida BLOQUEADA: ${specPath}\n\nLa fábrica no construyó nada: estas decisiones son de producto y no se pueden asumir.\n\n${preguntas}\n`
258	    + `## Cómo continuar\n\nResolver cada punto EN EL SPEC (\`${specPath}\`) y volver a ejecutar:\n\n    node factory/cli.mjs run ${specPath}\n`;
259	  escribir(c.ruta('pregunta.md'), md);
260	  c.etapa('analisis', 'BLOQUEADO', `${bordes.length} ambigüedad(es) bloqueante(s). Ver ${c.ruta('pregunta.md')}.`);
261	  c.log('analisis', `BLOQUEADO: ${bordes.length} ambigüedad(es) bloqueante(s). No se construye nada.`, md);
262	  shOk(`git add -A ${specDir} ${c.dir}${existe('ia/transcripciones') ? ' ia/transcripciones' : ''}`);
263	  shOk(`git commit -q -m "chore(${c.estado.corrida}): corrida bloqueada por ambigüedad" -m "Preguntas en ${c.ruta('pregunta.md')}."`);
264	  const p = sh(`git push -q origin ${rama}`);
265	  if (p.code !== 0) console.error(`Aviso: no se pudo subir la rama ${rama}; queda solo en local.`);
266	  shOk('git checkout -q main');
267	  return 4;
268	}
269	
270	/**
271	 * Pruebas de regresión aprobadas que el spec cambia a propósito (como pantallas_afectadas, pero para aserciones).
272	 * La fábrica aplica el reemplazo exacto del plan; la IA no edita esos archivos. El PR lo muestra y lo aprueba un humano.
273	 */
274	function aplicarPruebasAfectadas(c, plan) {
275	  const problemas = [];
276	  for (const d of plan.pruebas_afectadas || []) {
277	    const texto = leer(d.archivo);
278	    if (texto.includes(d.despues) && !texto.includes(d.antes)) continue; // ya aplicado en una corrida reanudada
279	    if (texto.split(d.antes).length !== 2) { problemas.push(`${d.archivo}: el texto a reemplazar debe aparecer exactamente una vez: ${d.antes}`); continue; }
280	    escribir(d.archivo, texto.replace(d.antes, d.despues));
281	    c.log('implementacion', `Prueba aprobada actualizada, pendiente de aprobación humana: ${d.archivo}`, `- ${d.antes}\n+ ${d.despues}\nMotivo: ${d.motivo}`);
282	  }
283	  return problemas;
284	}
285	
286	function validarPlan(p, specId) {
287	  const req = ['spec_id', 'titulo', 'naturaleza', 'capa_justificacion', 'criterios', 'bordes'];
288	  for (const k of req) if (p[k] === undefined) throw new Error(`falta "${k}"`);
289	  for (const b of p.bordes) {
290	    if (b.bloqueante !== undefined && typeof b.bloqueante !== 'boolean') throw new Error(`bloqueante debe ser true o false: ${b.descripcion}`);
291	    if (b.bloqueante && !b.preguntaria) throw new Error(`borde bloqueante sin pregunta: ${b.descripcion}`);
292	  }
293	  for (const d of p.pruebas_afectadas || []) {
294	    if (!d.archivo || !d.antes || !d.despues || !d.motivo) throw new Error(`pruebas_afectadas incompleta: ${JSON.stringify(d)}`);
295	    if (!/^(salidas\/[^/]+\/pruebas|factory\/regresion)\//.test(d.archivo)) throw new Error(`pruebas_afectadas fuera de las pruebas: ${d.archivo}`);
296	    if (d.archivo.startsWith(`salidas/${specId}/`)) throw new Error(`pruebas_afectadas es para pruebas de otros specs: ${d.archivo}`);
297	  }
298	  if (p.spec_id !== specId) throw new Error(`spec_id debe ser "${specId}"`);
299	  if (!Array.isArray(p.criterios) || !p.criterios.length) throw new Error('criterios vacío');
300	  for (const ca of p.criterios) if (!ca.id || !ca.texto || !ca.verificacion) throw new Error(`criterio incompleto: ${JSON.stringify(ca)}`);
301	  if (p.componente && !/^(quizaccess|local|quiz|block|qbank|qtype|qbehaviour|report|tool|theme)_[a-z0-9_]+$/.test(p.componente)) throw new Error(`componente inválido: ${p.componente}`);
302	  if (p.componente && !/^public\//.test(p.ruta_moodle || '')) throw new Error('ruta_moodle debe empezar con public/ (Moodle >= 5.1)');
303	  return p;
304	}
305	
306	function ejecutarSondas(c, sondas) {
307	  const out = [];
308	  for (const s of sondas.slice(0, 8)) {
309	    const body = s.body !== undefined ? `-H 'Content-Type: application/json' --data '${JSON.stringify(s.body).replace(/'/g, "'\\''")}'` : '';
310	    const r = sh(`curl -s -m 15 -X ${s.metodo || 'GET'} ${body} -w '\\n__HTTP__%{http_code}' '${s.url}'`);
311	    const [cuerpo, code] = r.out.split('\n__HTTP__');
312	    out.push({ ...s, respuesta: { http: Number(code), cuerpo: cuerpo.slice(0, 4000) } });
313	    c.log('sonda', `${s.metodo || 'GET'} ${s.url} -> HTTP ${code}`, `${s.descripcion || ''}\n${cuerpo.slice(0, 1500)}`);
314	  }
315	  return out;
316	}
317	
318	function validacionesEstaticas(c, specDir, plan) {
319	  const p = [];
320	  const plugins = moodle.pluginsDe(specDir);
321	  if (plan.componente) {
322	    const esperado = plugins.find((x) => x.componente === plan.componente);
323	    if (!esperado) p.push(`No existe ${specDir}/codigo/${plan.ruta_moodle}/version.php con $plugin->component = '${plan.componente}'.`);
324	    else if (esperado.rel !== plan.ruta_moodle) p.push(`El plugin está en ${esperado.rel} pero el plan dice ${plan.ruta_moodle}.`);
325	  }
326	  p.push(...moodle.lintPHP(specDir).map((x) => `Error de sintaxis PHP: ${x}`));
327	  const pruebas = archivos(`${specDir}/pruebas`, (f) => f.endsWith('.spec.ts'));
328	  if (!pruebas.length) p.push(`No hay pruebas en ${specDir}/pruebas/*.spec.ts`);
329	  const textoPruebas = pruebas.map((f) => leer(f)).join('\n');
330	  p.push(...copiasDeHelpers(archivos(`${specDir}/pruebas`, (f) => f.endsWith('.ts')).map((f) => ({ archivo: f, texto: leer(f) }))));
331	  // El corrector puede resolverlas; si llegaran a la etapa 8 detendrían la corrida sin PR.
332	  p.push(...auditar({}).hallazgos.filter((h) => REGLAS_ESTATICAS.has(h.regla)).map((h) => `[${h.regla}] ${h.donde}: ${h.detalle}`));
333	  for (const ca of plan.criterios) {
334	    if (ca.verificacion === 'proceso') continue;
335	    if (!textoPruebas.includes(`[${ca.id}]`)) p.push(`Ninguna prueba cubre ${ca.id} (el título debe incluir "[${ca.id}]").`);
336	  }
337	  c.log('validacion', p.length ? `${p.length} problema(s) estáticos.` : 'Validaciones estáticas OK (estructura, sintaxis PHP, cobertura de criterios).', p.join('\n') || null);
338	  return p;
339	}
340	
341	function rutasPluginsDesplegados() {
342	  return fs.readdirSync(path.join(RAIZ, 'salidas')).flatMap((s) => moodle.pluginsDe(`salidas/${s}`).map((p) => p.rel));
343	}
344	
345	function abrirPR(c, rama, plan, specDir, st, txtH, nuevas) {
346	  const cuerpo = `## ${plan.titulo}\n\nPropuesto por la fábrica a partir de \`${specDir}/spec.md\`. **El pipeline se detiene aquí: requiere aprobación humana. No mergea ni despliega.**\n\n`
347	    + `### Capa elegida\n\`${plan.componente || 'solo pruebas'}\` (${plan.ruta_moodle || '—'})\n\n${plan.capa_justificacion}\n\n`
348	    + `### Bordes del spec y criterio aplicado\n${plan.bordes.map((b) => `- **${b.descripcion}** → ${b.decision} _(${b.criterio})_`).join('\n')}\n\n`
349	    + `### Evidencia\n- Trazabilidad: \`${specDir}/trazabilidad.md\`\n- Diff: \`${specDir}/cambios.diff\`\n- Corrida: \`${c.dir}/\` (pipeline.log, funcional.xml, visual/, honestidad.log)\n`
350	    + `- Suite completa: ${st.passed} OK, ${st.failed} fallidas, ${st.skipped} omitidas\n\n`
351	    + (nuevas.length ? `### ⚠️ Líneas base visuales NUEVAS — revisar y aprobar\n${nuevas.map((n) => `- \`visual/lineas-base/${n}\``).join('\n')}\nAprobar con: \`node factory/cli.mjs aprobar-linea-base --pendientes --razon "..."\`\n\n` : '')
352	    + ((plan.pruebas_afectadas || []).length ? `### ⚠️ Pruebas aprobadas modificadas — revisar y aprobar\n${plan.pruebas_afectadas.map((d) => `- \`${d.archivo}\`: ${d.motivo}\n\n  \`\`\`diff\n  - ${d.antes}\n  + ${d.despues}\n  \`\`\``).join('\n')}\n\n` : '')
353	    + `### Control de verificación honesta\n\`\`\`\n${txtH}\`\`\`\n`;
354	  escribir(c.ruta('pr.md'), cuerpo);
355	  const push = sh(`git push -q -u origin ${rama}`);
356	  if (push.code !== 0) { c.log('pr', 'No se pudo hacer push (¿sin remoto/credenciales?). El PR queda descrito en pr.md.', push.err); return `(local) ${c.ruta('pr.md')}`; }
357	  const r = sh(`gh pr create --base main --head ${rama} --title "[${plan.spec_id}] ${plan.titulo}" --body-file ${c.ruta('pr.md')}`);
358	  return r.code === 0 ? r.out.trim() : `(no creado: ${r.err.trim()}) ${c.ruta('pr.md')}`;
359	}
360	
361	// ---------------------------------------------------------------------------------------------------------
362	async function suite() {
363	  const c = corridaActiva = new Corrida('suite');
364	  c.iniciarEstado(ETAPAS_SUITE);
365	  if (!moodle.moodleArriba()) return falla(c, 'precondicion', 'Moodle no responde. Ejecutar: bash entorno/setup.sh');
366	  c.etapa('precondicion', 'VALIDADO', 'Moodle responde.');
367	  for (const s of fs.readdirSync(path.join(RAIZ, 'salidas'))) if (moodle.pluginsDe(`salidas/${s}`).length) {
368	    const d = moodle.desplegar(`salidas/${s}`);
369	    c.log('despliegue', `${s}: ${d.ok ? 'OK' : 'FALLÓ'}`, d.ok ? null : d.salida);
370	  }
371	  moodle.reset();
372	  const r = correrPruebas(resto.filter((a) => !a.startsWith('--')), c.dir);
373	  const s = resumen(r.resultados);
374	  c.log('suite', `Funcional + visual: ${s.passed} OK, ${s.failed} fallidas, ${s.skipped} omitidas. Reporte: ${c.dir}/visual/index.html`, s.failed ? contextoFallos(c.dir, r.resultados) : null);
375	  if (s.failed) copiarDiferencias(c);
376	  c.etapa('pruebas', s.failed ? 'FALLIDO' : 'VALIDADO', `${s.passed} OK, ${s.failed} fallidas, ${s.skipped} omitidas.`);
377	  const { hallazgos: H, texto: txtH } = auditar({ resultados: r.resultados });
378	  escribir(c.ruta('honestidad.log'), txtH);
379	  c.log('honestidad', H.length ? `BLOQUEADO con ${H.length} hallazgo(s).` : 'OK.', txtH);
380	  c.etapa('honestidad', H.length ? 'FALLIDO' : 'VALIDADO', H.length ? `${H.length} hallazgo(s).` : 'Sin hallazgos.');
381	  return s.failed || H.length ? 1 : 0;
382	}
383	
384	/** Copia esperada/obtenida/diferencia de las comparaciones visuales fallidas a visual/diferencias/<corrida>/ */
385	function copiarDiferencias(c) {
386	  const art = path.join(RAIZ, c.dir, 'artefactos');
387	  if (!fs.existsSync(art)) return;
388	  for (const f of fs.readdirSync(art, { recursive: true }).filter((x) => /-(expected|actual|diff)\.png$/.test(x))) {
389	    fs.mkdirSync(path.join(RAIZ, 'visual/diferencias', c.id), { recursive: true });
390	    fs.copyFileSync(path.join(art, f), path.join(RAIZ, 'visual/diferencias', c.id, path.basename(path.dirname(f)) + '--' + path.basename(f)));
391	  }
392	  c.log('visual', `Imágenes esperada/obtenida/diferencia copiadas a visual/diferencias/${c.id}/`);
393	}
394	
395	async function honestidad() {
396	  const cargar = (bandera) => { const p = opt(bandera); return p ? JSON.parse(leer(p)) : undefined; };
397	  const { hallazgos: H, texto } = auditar({ resultados: cargar('--resultados'), sinFeature: cargar('--sin-feature'), plan: cargar('--plan') });
398	  process.stdout.write(texto);
399	  return H.length ? 1 : 0;
400	}
401	
402	async function aprobarLB() {
403	  const razon = opt('--razon');
404	  if (!razon || razon.length < 15) throw new Error('Aprobar una línea base exige --razon "<qué cambió a propósito y por qué>" (mín. 15 caracteres).');
405	  const quien = sh('git config user.name').out.trim() || process.env.USER;
406	  const objetivos = resto.includes('--pendientes') ? null : resto.filter((a) => a.endsWith('.png'));
407	  const hechos = aprobarLineaBase(objetivos, razon, quien);
408	  console.log(hechos.length ? `Aprobadas por ${quien}:\n${hechos.join('\n')}` : 'Nada que aprobar.');
409	  return 0;
410	}
411	
412	async function aprobarPruebas() {
413	  const razon = opt('--razon');
414	  if (!razon || razon.length < 15) throw new Error('Aprobar el manifiesto de pruebas exige --razon (mín. 15 caracteres).');
415	  // Importación dinámica a propósito: nada de la copia de trabajo de factory/honestidad/ se carga al auditar.
416	  const { construirManifiesto } = await import('./honestidad/verificar.mjs');
417	  const m = construirManifiesto();
418	  escribir('factory/honestidad/manifiesto.json', JSON.stringify(m, null, 2) + '\n');
419	  fs.appendFileSync(path.join(RAIZ, 'factory/honestidad/aprobaciones.log'), `${new Date().toISOString()} ${sh('git config user.name').out.trim()}: ${Object.keys(m.pruebas).length} pruebas — ${razon}\n`);
420	  console.log(`Manifiesto actualizado (${Object.keys(m.pruebas).length} pruebas). Se vuelve referencia cuando se mergea a main.`);
421	  return 0;
422	}
