454	    public function data_preprocessing(&$toform) {
455	        if (isset($toform['grade'])) {
456	            // Convert to a real number, so we don't get 0.0000.
457	            $toform['grade'] = $toform['grade'] + 0;
458	        }
459	
460	        if (count($this->_feedbacks)) {
461	            $key = 0;
462	            foreach ($this->_feedbacks as $feedback) {
463	                $draftid = file_get_submitted_draft_itemid('feedbacktext['.$key.']');
464	                $toform['feedbacktext['.$key.']']['text'] = file_prepare_draft_area(
465	                    $draftid,               // Draftid.
466	                    $this->context->id,     // Context.
467	                    'mod_quiz',             // Component.
468	                    'feedback',             // Filarea.
469	                    !empty($feedback->id) ? (int) $feedback->id : null, // Itemid.
470	                    null,
471	                    $feedback->feedbacktext // Text.
472	                );
473	                $toform['feedbacktext['.$key.']']['format'] = $feedback->feedbacktextformat;
474	                $toform['feedbacktext['.$key.']']['itemid'] = $draftid;
475	
476	                if ($toform['grade'] == 0) {
477	                    // When a quiz is un-graded, there can only be one lot of
478	                    // feedback. If the quiz previously had a maximum grade and
479	                    // several lots of feedback, we must now avoid putting text
480	                    // into input boxes that are disabled, but which the
481	                    // validation will insist are blank.
482	                    break;
483	                }
484	
485	                if ($feedback->mingrade > 0) {
486	                    $toform['feedbackboundaries['.$key.']'] =
487	                            round(100.0 * $feedback->mingrade / $toform['grade'], 6) . '%';
488	                }
489	                $key++;
490	            }
491	        }
492	
493	        if (isset($toform['timelimit'])) {
494	            $toform['timelimitenable'] = $toform['timelimit'] > 0;
495	        }
496	
497	        $this->preprocessing_review_settings($toform, 'during',
498	                display_options::DURING);
499	        $this->preprocessing_review_settings($toform, 'immediately',
500	                display_options::IMMEDIATELY_AFTER);
501	        $this->preprocessing_review_settings($toform, 'open',
502	                display_options::LATER_WHILE_OPEN);
503	        $this->preprocessing_review_settings($toform, 'closed',
504	                display_options::AFTER_CLOSE);
505	        $toform['attemptduring'] = true;
506	        $toform['overallfeedbackduring'] = false;
507	
508	        // Password field - different in form to stop browsers that remember
509	        // passwords from getting confused.
510	        if (isset($toform['password'])) {
511	            $toform['quizpassword'] = $toform['password'];
512	            unset($toform['password']);
513	        }
514	
515	        // Load any settings belonging to the access rules.
516	        if (!empty($toform['instance'])) {
517	            $accesssettings = access_manager::load_settings($toform['instance']);
518	            foreach ($accesssettings as $name => $value) {
519	                $toform[$name] = $value;
520	            }
521	        }
522	
523	        $suffix = $this->get_suffix();
524	        $completionminattemptsel = 'completionminattempts' . $suffix;
525	        if (empty($toform[$completionminattemptsel])) {
526	            $toform[$completionminattemptsel] = 1;
527	        } else {
528	            $completionminattemptsenabledel = 'completionminattemptsenabled' . $suffix;
529	            $toform[$completionminattemptsenabledel] = $toform[$completionminattemptsel] > 0;
530	        }
531	    }
