554	    public function validation($data, $files) {
555	        $errors = parent::validation($data, $files);
556	
557	        // Check open and close times are consistent.
558	        if ($data['timeopen'] != 0 && $data['timeclose'] != 0 &&
559	                $data['timeclose'] < $data['timeopen']) {
560	            $errors['timeclose'] = get_string('closebeforeopen', 'quiz');
561	        }
562	
563	        // Check duedate and open time are consistent.
564	        if (
565	            $data['timeopen'] != 0 && $data['duedate'] != 0 &&
566	            $data['duedate'] <= $data['timeopen']
567	        ) {
568	            $errors['duedate'] = get_string('duedatebeforeopen', 'quiz');
569	        }
570	
571	        // Check duedate and close time are consistent.
572	        if (
573	            $data['timeclose'] != 0 && $data['duedate'] != 0 &&
574	            $data['duedate'] > $data['timeclose']
575	        ) {
576	            $errors['duedate'] = get_string('duedateafterclose', 'quiz');
577	        }
578	
579	        // Check that the grace period is not too short.
580	        if ($data['overduehandling'] == 'graceperiod') {
581	            $graceperiodmin = get_config('quiz', 'graceperiodmin');
582	            if ($data['graceperiod'] <= $graceperiodmin) {
583	                $errors['graceperiod'] = get_string('graceperiodtoosmall', 'quiz', format_time($graceperiodmin));
584	            }
585	        }
586	
587	        $suffix = $this->get_suffix();
588	        $completionminattemptsel = 'completionminattempts' . $suffix;
589	        if (!empty($data[$completionminattemptsel])) {
590	            if ($data['attempts'] > 0 && $data[$completionminattemptsel] > $data['attempts']) {
591	                $completionminattemptsgroupel = 'completionminattemptsgroup' . $suffix;
592	                $errors[$completionminattemptsgroupel] = get_string('completionminattemptserror', 'quiz');
593	            }
594	        }
595	
596	        // Check the boundary value is a number or a percentage, and in range.
597	        $i = 0;
598	        while (!empty($data['feedbackboundaries'][$i] )) {
599	            $boundary = trim($data['feedbackboundaries'][$i]);
600	            if (strlen($boundary) > 0) {
601	                if ($boundary[strlen($boundary) - 1] == '%') {
602	                    $boundary = trim(substr($boundary, 0, -1));
603	                    if (is_numeric($boundary)) {
604	                        $boundary = $boundary * $data['grade'] / 100.0;
605	                    } else {
606	                        $errors["feedbackboundaries[$i]"] =
607	                                get_string('feedbackerrorboundaryformat', 'quiz', $i + 1);
608	                    }
609	                } else if (!is_numeric($boundary)) {
610	                    $errors["feedbackboundaries[$i]"] =
611	                            get_string('feedbackerrorboundaryformat', 'quiz', $i + 1);
612	                }
613	            }
614	            if (is_numeric($boundary) && $boundary <= 0 || $boundary >= $data['grade'] ) {
615	                $errors["feedbackboundaries[$i]"] =
616	                        get_string('feedbackerrorboundaryoutofrange', 'quiz', $i + 1);
617	            }
618	            if (is_numeric($boundary) && $i > 0 &&
619	                    $boundary >= $data['feedbackboundaries'][$i - 1]) {
620	                $errors["feedbackboundaries[$i]"] =
621	                        get_string('feedbackerrororder', 'quiz', $i + 1);
622	            }
623	            $data['feedbackboundaries'][$i] = $boundary;
624	            $i += 1;
625	        }
626	        $numboundaries = $i;
627	
628	        // Check there is nothing in the remaining unused fields.
629	        if (!empty($data['feedbackboundaries'])) {
630	            for ($i = $numboundaries; $i < count($data['feedbackboundaries']); $i += 1) {
631	                if (!empty($data['feedbackboundaries'][$i] ) &&
632	                        trim($data['feedbackboundaries'][$i] ) != '') {
633	                    $errors["feedbackboundaries[$i]"] =
634	                            get_string('feedbackerrorjunkinboundary', 'quiz', $i + 1);
635	                }
636	            }
637	        }
638	        for ($i = $numboundaries + 1; $i < count($data['feedbacktext']); $i += 1) {
639	            if (!empty($data['feedbacktext'][$i]['text']) &&
640	                    trim($data['feedbacktext'][$i]['text'] ) != '') {
641	                $errors["feedbacktext[$i]"] =
642	                        get_string('feedbackerrorjunkinfeedback', 'quiz', $i + 1);
643	            }
644	        }
645	
646	        // If CBM is involved, don't show the warning for grade to pass being larger than the maximum grade.
647	        if (($data['preferredbehaviour'] == 'deferredcbm') OR ($data['preferredbehaviour'] == 'immediatecbm')) {
648	            unset($errors['gradepass']);
649	        }
650	        // Any other rule plugins.
651	        $errors = access_manager::validate_settings_form_fields($errors, $data, $files, $this);
652	
653	        return $errors;
654	    }
