1003	    // Quiz feedback.
1004	    if (isset($quiz->feedbacktext)) {
1005	        // Clean up the boundary text.
1006	        for ($i = 0; $i < count($quiz->feedbacktext); $i += 1) {
1007	            if (empty($quiz->feedbacktext[$i]['text'])) {
1008	                $quiz->feedbacktext[$i]['text'] = '';
1009	            } else {
1010	                $quiz->feedbacktext[$i]['text'] = trim($quiz->feedbacktext[$i]['text']);
1011	            }
1012	        }
1013	
1014	        // Check the boundary value is a number or a percentage, and in range.
1015	        $i = 0;
1016	        while (!empty($quiz->feedbackboundaries[$i])) {
1017	            $boundary = trim($quiz->feedbackboundaries[$i]);
1018	            if (!is_numeric($boundary)) {
1019	                if (strlen($boundary) > 0 && $boundary[strlen($boundary) - 1] == '%') {
1020	                    $boundary = trim(substr($boundary, 0, -1));
1021	                    if (is_numeric($boundary)) {
1022	                        $boundary = $boundary * $quiz->grade / 100.0;
1023	                    } else {
1024	                        return get_string('feedbackerrorboundaryformat', 'quiz', $i + 1);
1025	                    }
1026	                }
1027	            }
1028	            if ($boundary <= 0 || $boundary >= $quiz->grade) {
1029	                return get_string('feedbackerrorboundaryoutofrange', 'quiz', $i + 1);
1030	            }
1031	            if ($i > 0 && $boundary >= $quiz->feedbackboundaries[$i - 1]) {
1032	                return get_string('feedbackerrororder', 'quiz', $i + 1);
1033	            }
1034	            $quiz->feedbackboundaries[$i] = $boundary;
1035	            $i += 1;
1036	        }
1037	        $numboundaries = $i;
1038	
1039	        // Check there is nothing in the remaining unused fields.
1040	        if (!empty($quiz->feedbackboundaries)) {
1041	            for ($i = $numboundaries; $i < count($quiz->feedbackboundaries); $i += 1) {
1042	                if (!empty($quiz->feedbackboundaries[$i]) &&
1043	                        trim($quiz->feedbackboundaries[$i]) != '') {
1044	                    return get_string('feedbackerrorjunkinboundary', 'quiz', $i + 1);
1045	                }
1046	            }
1047	        }
1048	        for ($i = $numboundaries + 1; $i < count($quiz->feedbacktext); $i += 1) {
1049	            if (!empty($quiz->feedbacktext[$i]['text']) &&
1050	                    trim($quiz->feedbacktext[$i]['text']) != '') {
1051	                return get_string('feedbackerrorjunkinfeedback', 'quiz', $i + 1);
1052	            }
1053	        }
1054	        // Needs to be bigger than $quiz->grade because of '<' test in quiz_feedback_for_grade().
1055	        $quiz->feedbackboundaries[-1] = $quiz->grade + 1;
1056	        $quiz->feedbackboundaries[$numboundaries] = 0;
1057	        $quiz->feedbackboundarycount = $numboundaries;
1058	    } else {
1059	        $quiz->feedbackboundarycount = -1;
1060	    }
1061	
1062	    // Combing the individual settings into the review columns.
1063	    $quiz->reviewattempt = quiz_review_option_form_to_db($quiz, 'attempt');
