1065	    $quiz->reviewmaxmarks = quiz_review_option_form_to_db($quiz, 'maxmarks');
1066	    $quiz->reviewmarks = quiz_review_option_form_to_db($quiz, 'marks');
1067	    $quiz->reviewspecificfeedback = quiz_review_option_form_to_db($quiz, 'specificfeedback');
1068	    $quiz->reviewgeneralfeedback = quiz_review_option_form_to_db($quiz, 'generalfeedback');
1069	    $quiz->reviewrightanswer = quiz_review_option_form_to_db($quiz, 'rightanswer');
1070	    $quiz->reviewoverallfeedback = quiz_review_option_form_to_db($quiz, 'overallfeedback');
1071	    $quiz->reviewattempt |= display_options::DURING;
1072	    $quiz->reviewoverallfeedback &= ~display_options::DURING;
1073	
1074	    // Ensure that disabled checkboxes in completion settings are set to 0.
1075	    // But only if the completion settinsg are unlocked.
1076	    if (!empty($quiz->completionunlocked)) {
1077	        if (empty($quiz->completionusegrade)) {
1078	            $quiz->completionpassgrade = 0;
1079	        }
1080	        if (empty($quiz->completionpassgrade)) {
1081	            $quiz->completionattemptsexhausted = 0;
1082	        }
1083	        if (empty($quiz->completionminattemptsenabled)) {
1084	            $quiz->completionminattempts = 0;
1085	        }
1086	    }
