 */
public function get_slots($page = 'all') {
    if ($page === 'all') {
        $numbers = [];
        foreach ($this->pagelayout as $numbersonpage) {
            $numbers = array_merge($numbers, $numbersonpage);
        }
        return $numbers;
    } else {
        return $this->pagelayout[$page];
    }
}

