2	// Identidad del sitio: español e imagen propia, sin tocar el core de Moodle.
3	//   - Instala el paquete de idioma es y lo deja como idioma del sitio y de todos los usuarios.
4	//   - Traduce el contenido sembrado, conservando su estructura: misma opción correcta, mismos temas, mismas notas.
5	//   - Aplica el diseño como ajustes del tema Boost (en base de datos): no agrega archivos al árbol de Moodle.
6	// Idempotente. Uso: php /opt/seed/identidad.php   (como www-data, dentro del contenedor web)
7	define('CLI_SCRIPT', true);
8	require('/var/www/moodle/config.php');
9	require_once($CFG->libdir . '/filelib.php');
10	
11	global $DB;
12	\core\session\manager::set_user(get_admin());
13	
14	// 1. Idioma
15	if (!get_string_manager()->translation_exists('es', false)) {
16	    (new \tool_langimport\controller())->install_languagepacks('es', false);
17	    get_string_manager(true)->reset_caches();
18	    if (!get_string_manager()->translation_exists('es', false)) {
19	        fwrite(STDERR, "No se pudo instalar el paquete de idioma es: revisar la conexión con download.moodle.org\n");
20	        exit(1);
21	    }
22	}
23	set_config('lang', 'es');
24	set_config('autolang', 0); // el idioma del navegador no debe cambiar el sitio: las pruebas y capturas serían distintas
25	set_config('langmenu', 0);
26	$DB->set_field_select('user', 'lang', 'es', 'deleted = 0');
27	
28	// Cadenas sin traducir o mal traducidas en el paquete es: se corrigen como traducción local, fuera del core.
29	$local = $CFG->dataroot . '/lang/es_local';
30	make_writable_directory($local);
31	$cadenas = [
32	    'quiz.php' => ['attemptsubmitted' => 'Intento enviado.', 'feedback' => 'Retroalimentación'],
33	    'moodle.php' => ['loginwelcometitle' => 'Viaro Exámenes',
34	        'loginwelcomedescription' => 'Evaluaciones claras para estudiantes y docentes. Inicia sesión para continuar.'],
35	];
36	foreach ($cadenas as $archivo => $lista) {
37	    $php = "<?php\n";
38	    foreach ($lista as $clave => $texto) {
39	        $php .= '$string[' . var_export($clave, true) . '] = ' . var_export($texto, true) . ";\n";
40	    }
41	    file_put_contents("{$local}/{$archivo}", $php);
42	}
43	
44	// 2. Nombre del sitio
45	$sitio = get_site();
46	$sitio->fullname = 'Viaro Exámenes';
47	$sitio->shortname = 'Viaro';
48	$DB->update_record('course', $sitio);
49	
50	// 3. Contenido sembrado en español. El orden de las opciones se conserva: la primera es la correcta.
51	$preguntas = [
52	    'ALG-1 Opción múltiple' => [
53	        'texto' => '¿Cuánto es 3 × 4?',
54	        'opciones' => [['12', '12 es el resultado de sumar cuatro veces el 3.'], ['7', '7 es la suma, no el producto.'],
55	            ['9', '9 es 3 × 3.'], ['10', '10 no es múltiplo de 3.']],
56	        'general' => '3 × 4 = 12.',
57	    ],
58	    'ALG-2 Verdadero o falso' => ['texto' => 'La suma de dos números pares siempre es par.', 'general' => 'Dos pares suman siempre un múltiplo de 2.'],
59	    'GEO-1 Opción múltiple' => [
60	        'texto' => '¿Cuántos lados tiene un hexágono?',
61	        'opciones' => [['6', 'Hexa significa seis.'], ['4', 'Cuatro lados tiene un cuadrilátero.'],
62	            ['5', 'Cinco lados tiene un pentágono.'], ['8', 'Ocho lados tiene un octágono.']],
63	        'general' => 'Un hexágono tiene seis lados.',
64	    ],
65	    'GEO-2 Verdadero o falso' => ['texto' => 'Todo cuadrado es también un rectángulo.', 'general' => 'Un cuadrado tiene cuatro ángulos rectos.'],
66	    'HIS-1 Verdadero o falso' => ['texto' => 'Guatemala declaró su independencia en 1821.', 'general' => 'El Acta de Independencia se firmó el 15 de septiembre de 1821.'],
67	    'HIS-2 Ensayo' => [
68	        'texto' => 'Explica en un párrafo una consecuencia de la independencia de Centroamérica.',
69	        'general' => 'Una buena respuesta nombra la consecuencia y explica por qué ocurrió.',
70	        'calificador' => 'Valorar que la consecuencia sea correcta y esté explicada.',
71	    ],
72	];
73	foreach ($preguntas as $nombre => $p) {
74	    foreach ($DB->get_records('question', ['name' => $nombre]) as $q) {
75	        $DB->update_record('question', (object) ['id' => $q->id, 'questiontext' => "<p>{$p['texto']}</p>",
76	            'questiontextformat' => FORMAT_HTML, 'generalfeedback' => "<p>{$p['general']}</p>", 'generalfeedbackformat' => FORMAT_HTML]);
77	        $respuestas = array_values($DB->get_records('question_answers', ['question' => $q->id], 'id'));
78	        if ($q->qtype === 'multichoice') {
79	            foreach ($respuestas as $i => $r) {
80	                $DB->update_record('question_answers', (object) ['id' => $r->id, 'answer' => $p['opciones'][$i][0],
81	                    'answerformat' => FORMAT_HTML, 'feedback' => $p['opciones'][$i][1], 'feedbackformat' => FORMAT_HTML]);
82	            }
83	            $DB->set_field('qtype_multichoice_options', 'correctfeedback', 'Respuesta correcta.', ['questionid' => $q->id]);
84	            $DB->set_field('qtype_multichoice_options', 'partiallycorrectfeedback', 'Respuesta parcialmente correcta.', ['questionid' => $q->id]);
85	            $DB->set_field('qtype_multichoice_options', 'incorrectfeedback', 'Respuesta incorrecta.', ['questionid' => $q->id]);
86	        } else if ($q->qtype === 'truefalse') {
87	            foreach ($respuestas as $r) {
88	                $DB->set_field('question_answers', 'feedback', $r->fraction > 0 ? 'Correcto.' : 'Incorrecto.', ['id' => $r->id]);
89	            }
90	        } else if ($q->qtype === 'essay') {
91	            $DB->set_field('qtype_essay_options', 'graderinfo', "<p>{$p['calificador']}</p>", ['questionid' => $q->id]);
92	            $DB->set_field('qtype_essay_options', 'graderinfoformat', FORMAT_HTML, ['questionid' => $q->id]);
93	        }
94	    }
95	}
96	
97	$DB->set_field('quiz', 'intro', '<p>Examen de práctica con preguntas de álgebra, geometría e historia.</p>', ['name' => 'Examen de regresión']);
98	
99	// 4. Diseño: ajustes de Boost
100	set_config('theme', 'boost');
101	set_config('scsspre', file_get_contents(__DIR__ . '/tema-variables.scss'), 'theme_boost');
102	set_config('scss', file_get_contents(__DIR__ . '/tema.scss'), 'theme_boost');
103	
104	purge_all_caches();
105	echo "Identidad OK: español, Viaro Exámenes y tema aplicado\n";
