// Delete all tag areas, collections and instances associated with this plugin.
core_tag_area::uninstall($component);

// Custom plugin uninstall.
$plugindirectory = core_component::get_plugin_directory($type, $name);
$uninstalllib = $plugindirectory . '/db/uninstall.php';
if (file_exists($uninstalllib)) {
    require_once($uninstalllib);
    $uninstallfunction = 'xmldb_' . $pluginname . '_uninstall';    // eg. 'xmldb_workshop_uninstall()'
    if (function_exists($uninstallfunction)) {
        // Do not verify result, let plugin complain if necessary.
        $uninstallfunction();
    }
}

// Specific plugin type cleanup.
$plugininfo = core_plugin_manager::instance()->get_plugin_info($component);
if ($plugininfo) {
    $plugininfo->uninstall_cleanup();
    core_plugin_manager::reset_caches();
}
$plugininfo = null;

// Perform clean-up task common for all the plugin/subplugin types.

// Delete the web service functions and pre-built services.
\core_external\util::delete_service_descriptions($component);

// delete calendar events
$DB->delete_records('event', array('modulename' => $pluginname));
$DB->delete_records('event', ['component' => $component]);

// Delete scheduled tasks.
$DB->delete_records('task_adhoc', ['component' => $component]);
$DB->delete_records('task_scheduled', array('component' => $component));

// Delete Inbound Message datakeys.
$DB->delete_records_select('messageinbound_datakeys',
        'handler IN (SELECT id FROM {messageinbound_handlers} WHERE component = ?)', array($component));

// Delete Inbound Message handlers.
$DB->delete_records('messageinbound_handlers', array('component' => $component));

// delete all the logs
$DB->delete_records('log', array('module' => $pluginname));

// delete log_display information
$DB->delete_records('log_display', array('component' => $component));

// delete the module configuration records
unset_all_config_for_plugin($component);
if ($type === 'mod') {
    unset_all_config_for_plugin($pluginname);
}

// Wipe any xAPI state information.
if (core_xapi\handler::supports_xapi($component)) {
    core_xapi\api::remove_states_from_component($component);
}

// delete message provider
message_provider_uninstall($component);

// delete the plugin tables
$xmldbfilepath = $plugindirectory . '/db/install.xml';
drop_plugin_tables($component, $xmldbfilepath, false);
if ($type === 'mod' or $type === 'block') {
    // non-frankenstyle table prefixes
    drop_plugin_tables($name, $xmldbfilepath, false);
}

// delete the capabilities that were defined by this module
capabilities_cleanup($component);

// Delete all remaining files in the filepool owned by the component.
$fs = get_file_storage();
$fs->delete_component_files($component);

// Finally purge all caches.

import { defineConfig, devices } from '@playwright/test';

// Corre SIEMPRE dentro de mcr.microsoft.com/playwright:v1.64.1-noble (ver factory/lib/suite.mjs),
// para que el renderizado (fuentes, antialiasing) sea idéntico en cualquier máquina.
const OUT = process.env.QA_OUT || 'test-results/ultima';

export default defineConfig({
  testDir: '.',
  testMatch: ['factory/regresion/**/*.spec.ts', 'salidas/*/pruebas/**/*.spec.ts'],
  // Estado compartido (un solo Moodle): secuencial y determinista.
  workers: 1,
  fullyParallel: false,
  // Sin reintentos: un reintento automático esconde pruebas inestables. Si algo es flaky, se arregla.
  retries: 0,
  timeout: 90_000,
  outputDir: `${OUT}/artefactos`,
  reporter: [
    ['list'],
    ['junit', { outputFile: `${OUT}/funcional.xml` }],
    ['json', { outputFile: `${OUT}/resultados.json` }],
    ['html', { outputFolder: `${OUT}/visual`, open: 'never' }],
  ],
  // Líneas base versionadas en el repo, un archivo por pantalla y viewport.
  snapshotPathTemplate: 'visual/lineas-base/{arg}--{projectName}{ext}',
  expect: {
    toHaveScreenshot: {
      // threshold: tolerancia de color POR PIXEL (YIQ, 0..1). 0.2 absorbe antialiasing de fuentes.
      // maxDiffPixelRatio: fracción de pixeles distintos tolerada en la pantalla. 0.002 = 0,2 %.
      //   Una fila nueva, un botón desplazado o un color de tema cambiado superan eso con holgura;
      //   el ruido de subpixel queda por debajo. Criterio y mediciones en cobertura.md.
      threshold: 0.2,
      maxDiffPixelRatio: 0.002,
      animations: 'disabled',
      caret: 'hide',
      scale: 'css',
    },
  },
  use: {
    baseURL: process.env.BASE_URL || 'http://localhost:8090',
    locale: 'es-GT',
    timezoneId: 'America/Guatemala',
    // Una acción que no encuentra su elemento falla en 15 s, no al agotar el timeout de la prueba:
    // los fallos se diagnostican rápido y no consumen minutos del pipeline.
    actionTimeout: 15_000,
    navigationTimeout: 30_000,
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  projects: [
    { name: 'escritorio', use: { ...devices['Desktop Chrome'], viewport: { width: 1366, height: 900 } } },
    { name: 'movil', use: { ...devices['Pixel 7'] } },
  ],
});

